function pad2(n: number): string {
  return n < 10 ? `0${n}` : `${n}`;
}

export function computeDecisionCutoffUtc(deliveryDate: string, cutoffTimeUk: string): string {
  const [y, m, d] = deliveryDate.split('-').map(Number);
  const parts = cutoffTimeUk.trim().split(':').map(Number);
  const hh = parts[0] || 0;
  const mm = parts[1] || 0;
  const dt = new Date(Date.UTC(y, m - 1, d - 1, hh, mm, 0));
  return dt.toISOString().replace('.000Z', 'Z');
}

function percentileLinear(sortedArr: number[], p: number): number {
  if (sortedArr.length === 0) return 0;
  if (sortedArr.length === 1) return sortedArr[0];
  const idx = (p / 100) * (sortedArr.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  const weight = idx - lo;
  return sortedArr[lo] * (1 - weight) + sortedArr[hi] * weight;
}

function round2(val: number): number {
  return Math.round(val * 100) / 100;
}

export function computeMetricBundle(
  forecasts: number[],
  actuals: number[],
  mapeGuardMw: number = 100.0
): MetricBundle {
  const n = Math.min(forecasts.length, actuals.length);
  if (n === 0) {
    return {
      sampleCount: 0,
      maeMw: 0,
      rmseMw: 0,
      biasMw: 0,
      mapePercent: 0,
      mapeGuardedCount: 0,
      p50AbsErrorMw: 0,
      p90AbsErrorMw: 0,
      p95AbsErrorMw: 0,
      meanForecastMw: 0,
      meanActualMw: 0,
    };
  }

  let sumAbs = 0;
  let sumSq = 0;
  let sumSigned = 0;
  let sumFc = 0;
  let sumAct = 0;
  let sumApe = 0;
  let validApeCount = 0;
  let guardedCount = 0;
  const absErrors: number[] = [];
  const safeThreshold = Math.max(mapeGuardMw, 1e-6);

  for (let i = 0; i < n; i++) {
    const fc = forecasts[i];
    const act = actuals[i];
    const err = fc - act;
    const absErr = Math.abs(err);
    sumAbs += absErr;
    sumSq += err * err;
    sumSigned += err;
    sumFc += fc;
    sumAct += act;
    absErrors.push(absErr);

    if (Math.abs(act) >= safeThreshold) {
      sumApe += (absErr / Math.abs(act)) * 100.0;
      validApeCount += 1;
    } else {
      guardedCount += 1;
    }
  }

  absErrors.sort((a, b) => a - b);
  const mape = validApeCount > 0 ? sumApe / validApeCount : 0;

  return {
    sampleCount: n,
    maeMw: round2(sumAbs / n),
    rmseMw: round2(Math.sqrt(sumSq / n)),
    biasMw: round2(sumSigned / n),
    mapePercent: round2(mape),
    mapeGuardedCount: guardedCount,
    p50AbsErrorMw: round2(percentileLinear(absErrors, 50)),
    p90AbsErrorMw: round2(percentileLinear(absErrors, 90)),
    p95AbsErrorMw: round2(percentileLinear(absErrors, 95)),
    meanForecastMw: round2(sumFc / n),
    meanActualMw: round2(sumAct / n),
  };
}

export function selectDeliveryDayForecast(
  deliveryDate: string,
  cutoffTimeUk: string = '09:00',
  mapeGuardMw: number = 100.0
): DeliveryDayForecastResponse {
  const dayNum = Math.max(1, Math.min(31, Number(deliveryDate.split('-')[2]) || 1));
  const dayIdx = dayNum - 1;
  const cutoffUtc = computeDecisionCutoffUtc(deliveryDate, cutoffTimeUk);
  const cutoffMs = Date.parse(cutoffUtc);

  const dayRuns = PRELOADED_BMRS_DATA.runsByDay[dayIdx] || [];
  const intervals: DecisionIntervalPoint[] = [];
  const safeGuard = Math.max(mapeGuardMw, 1e-6);

  const [y, m, d] = deliveryDate.split('-').map(Number);
  const baseStartMs = Date.UTC(y, m - 1, d, 0, 0, 0);

  for (let sp = 0; sp < 48; sp++) {
    const startMs = baseStartMs + sp * 30 * 60 * 1000;
    const startDt = new Date(startMs);
    const startIso = startDt.toISOString().replace('.000Z', 'Z');
    const ukLocalTime = `${pad2(startDt.getUTCHours())}:${pad2(startDt.getUTCMinutes())}`;
    const actVal = PRELOADED_BMRS_DATA.actuals[dayIdx * 48 + sp];

    let bestPubIso: string | null = null;
    let bestPubMs = -1;
    let bestFcVal: number | null = null;
    let validCount = 0;
    let excludedCount = 0;

    for (let r = 0; r < dayRuns.length; r++) {
      const [pubIdx, vals] = dayRuns[r];
      const pubIso = PRELOADED_BMRS_DATA.pubTimes[pubIdx];
      const pubMs = Date.parse(pubIso);
      const fcCandidate = vals[sp];

      if (pubMs > cutoffMs || pubMs > startMs) {
        excludedCount += 1;
        continue;
      }
      validCount += 1;
      if (pubMs > bestPubMs) {
        bestPubMs = pubMs;
        bestPubIso = pubIso;
        bestFcVal = fcCandidate;
      }
    }

    const horizonHours =
      bestPubMs > 0 ? round2((startMs - bestPubMs) / (3600 * 1000)) : null;
    const errorMw =
      bestFcVal !== null && actVal !== null ? round2(bestFcVal - actVal) : null;
    const absErrorMw = errorMw !== null ? round2(Math.abs(errorMw)) : null;
    const apePercent =
      absErrorMw !== null && actVal !== null && Math.abs(actVal) >= safeGuard
        ? round2((absErrorMw / Math.abs(actVal)) * 100.0)
        : null;

    intervals.push({
      startTime: startIso,
      ukLocalTime,
      settlementPeriod: sp + 1,
      forecastGenerationMw: bestFcVal,
      actualGenerationMw: actVal,
      publishTime: bestPubIso,
      horizonHours,
      errorMw,
      absErrorMw,
      apePercent,
      candidatesAvailable: validCount,
      postCutoffExcluded: excludedCount,
    });
  }

  const fcs = intervals
    .map((p) => p.forecastGenerationMw)
    .filter((v): v is number => v !== null);
  const acts = intervals
    .map((p) => p.actualGenerationMw)
    .filter((v): v is number => v !== null);
  const horizons = intervals
    .map((p) => p.horizonHours)
    .filter((v): v is number => v !== null);
  const pubs = Array.from(
    new Set(intervals.map((p) => p.publishTime).filter((v): v is string => v !== null))
  ).sort();

  const dayMetrics = computeMetricBundle(fcs, acts, mapeGuardMw);
  const meanFc = fcs.length ? round2(fcs.reduce((a, b) => a + b, 0) / fcs.length) : 0;
  const meanAct = acts.length ? round2(acts.reduce((a, b) => a + b, 0) / acts.length) : null;
  const totalFcMwh = round2(fcs.reduce((a, b) => a + b * 0.5, 0));
  const totalActMwh = acts.length ? round2(acts.reduce((a, b) => a + b * 0.5, 0)) : null;

  const dMinus1Date = new Date(Date.UTC(y, m - 1, d - 1)).toISOString().slice(0, 10);
  const availableForecastRunsOnDMinus1 = dayRuns
    .map(([pubIdx]) => PRELOADED_BMRS_DATA.pubTimes[pubIdx])
    .filter((pt) => pt.startsWith(dMinus1Date))
    .sort();

  return {
    summary: {
      deliveryDate,
      decisionCutoffTimeUk: cutoffTimeUk,
      decisionCutoffTimestampUtc: cutoffUtc,
      totalIntervals: intervals.length,
      matchedActualIntervals: acts.length,
      meanForecastMw: meanFc,
      meanActualMw: meanAct,
      peakForecastMw: fcs.length ? Math.max(...fcs) : 0,
      peakActualMw: acts.length ? Math.max(...acts) : null,
      minForecastMw: fcs.length ? Math.min(...fcs) : 0,
      minActualMw: acts.length ? Math.min(...acts) : null,
      totalForecastEnergyMwh: totalFcMwh,
      totalActualEnergyMwh: totalActMwh,
      latestPublishTimeUsed: pubs.length ? pubs[pubs.length - 1] : null,
      earliestPublishTimeUsed: pubs.length ? pubs[0] : null,
      minHorizonHours: horizons.length ? Math.min(...horizons) : null,
      maxHorizonHours: horizons.length ? Math.max(...horizons) : null,
      meanHorizonHours: horizons.length
        ? round2(horizons.reduce((a, b) => a + b, 0) / horizons.length)
        : null,
      dayMaeMw: dayMetrics.maeMw,
      dayRmseMw: dayMetrics.rmseMw,
      dayBiasMw: dayMetrics.biasMw,
      dayMapePercent: dayMetrics.mapePercent,
      dayP90AbsErrorMw: dayMetrics.p90AbsErrorMw,
    },
    intervals,
    availableForecastRunsOnDMinus1,
  };
}

export function evaluateAccuracyReportClient(
  startDate: string = '2026-01-01',
  endDate: string = '2026-01-31',
  cutoffTimeUk: string = '09:00',
  mapeGuardMw: number = 100.0
): AccuracyReportResponse {
  const startDay = Math.max(1, Math.min(31, Number(startDate.split('-')[2]) || 1));
  const endDay = Math.max(startDay, Math.min(31, Number(endDate.split('-')[2]) || 31));

  const allPoints: Array<DecisionIntervalPoint & { deliveryDate: string; hourOfDay: number }> = [];
  const byDay: DailyBreakdownRow[] = [];
  const allHorizonPairs: Array<{ horizon: number; fc: number; act: number }> = [];

  for (let d = startDay; d <= endDay; d++) {
    const dStr = `2026-01-${pad2(d)}`;
    const dayIdx = d - 1;
    const dayRes = selectDeliveryDayForecast(dStr, cutoffTimeUk, mapeGuardMw);
    const dFcs: number[] = [];
    const dActs: number[] = [];
    let maxAbsErr = 0;
    let peakSignedErr = 0;

    for (const pt of dayRes.intervals) {
      if (pt.forecastGenerationMw !== null && pt.actualGenerationMw !== null) {
        dFcs.push(pt.forecastGenerationMw);
        dActs.push(pt.actualGenerationMw);
        const absE = Math.abs(pt.errorMw ?? 0);
        if (absE > maxAbsErr) {
          maxAbsErr = absE;
          peakSignedErr = pt.errorMw ?? 0;
        }
        const hr = Number(pt.ukLocalTime.split(':')[0]) || 0;
        allPoints.push({ ...pt, deliveryDate: dStr, hourOfDay: hr });
      }
    }

    const dayMetrics = computeMetricBundle(dFcs, dActs, mapeGuardMw);
    const directionLabel =
      dayMetrics.biasMw > 25
        ? 'Over-forecast'
        : dayMetrics.biasMw < -25
        ? 'Under-forecast'
        : 'Balanced';

    byDay.push({
      deliveryDate: dStr,
      publishTimeUsed: dayRes.summary.latestPublishTimeUsed,
      meanHorizonHours: dayRes.summary.meanHorizonHours || 0,
      peakErrorMw: peakSignedErr,
      directionLabel,
      metrics: dayMetrics,
    });

    const baseStartMs = Date.UTC(2026, 0, d, 0, 0, 0);
    const dayRuns = PRELOADED_BMRS_DATA.runsByDay[dayIdx] || [];
    for (const [pubIdx, vals] of dayRuns) {
      const pubMs = Date.parse(PRELOADED_BMRS_DATA.pubTimes[pubIdx]);
      for (let sp = 0; sp < 48; sp++) {
        const startMs = baseStartMs + sp * 30 * 60 * 1000;
        const h = (startMs - pubMs) / (3600 * 1000);
        if (h > 0) {
          allHorizonPairs.push({
            horizon: h,
            fc: vals[sp],
            act: PRELOADED_BMRS_DATA.actuals[dayIdx * 48 + sp],
          });
        }
      }
    }
  }

  const overall = computeMetricBundle(
    allPoints.map((p) => p.forecastGenerationMw as number),
    allPoints.map((p) => p.actualGenerationMw as number),
    mapeGuardMw
  );

  const p90Band = Math.round(overall.p90AbsErrorMw);
  const p50Band = Math.round(overall.p50AbsErrorMw);
  const p95Band = Math.round(overall.p95AbsErrorMw);
  const biasDir = overall.biasMw >= 0 ? 'over-forecasts' : 'under-forecasts';
  const biasAbs = Math.abs(Math.round(overall.biasMw));

  const coverageSummaryText = `Forecast ± ${p90Band.toLocaleString()} MW covers 90% of half-hourly outcomes (median error ± ${p50Band.toLocaleString()} MW; P95 ± ${p95Band.toLocaleString()} MW).`;
  const procurementGuidanceText = `At the ${cutoffTimeUk} UK D-1 decision cutoff, WINDFOR ${biasDir} actual wind generation by ${biasAbs.toLocaleString()} MW on average (Bias = ${overall.biasMw >= 0 ? '+' : ''}${overall.biasMw.toFixed(1)} MW, MAE = ${overall.maeMw.toFixed(1)} MW). Plan thermal cover around the lower edge of the ±${p90Band.toLocaleString()} MW band.`;

  const activeHorizons = allPoints.map((p) => p.horizonHours ?? 0);
  const minActiveH = activeHorizons.length ? Math.min(...activeHorizons) : 15;
  const maxActiveH = activeHorizons.length ? Math.max(...activeHorizons) : 39;

  const horizonDefs: Array<[string, number, number]> = [
    ['0–12h', 0, 12],
    ['12–24h', 12, 24],
    ['24–36h', 24, 36],
    ['36–48h', 36, 48],
    ['48h+', 48, 1000],
  ];

  const byHorizon: HorizonBreakdownRow[] = [];
  for (const [label, hMin, hMax] of horizonDefs) {
    const decisionSub = allPoints.filter((p) => {
      const h = p.horizonHours ?? 0;
      return h > hMin && h <= hMax;
    });
    const isDecisionWindow = maxActiveH > hMin && minActiveH <= hMax && decisionSub.length > 0;

    if (decisionSub.length > 0) {
      byHorizon.push({
        horizonBucket: label,
        minHorizonHours: hMin,
        maxHorizonHours: hMax,
        isDecisionWindow,
        metrics: computeMetricBundle(
          decisionSub.map((p) => p.forecastGenerationMw as number),
          decisionSub.map((p) => p.actualGenerationMw as number),
          mapeGuardMw
        ),
      });
    } else {
      const multiSub = allHorizonPairs.filter((p) => p.horizon > hMin && p.horizon <= hMax);
      if (multiSub.length > 0) {
        byHorizon.push({
          horizonBucket: label,
          minHorizonHours: hMin,
          maxHorizonHours: hMax,
          isDecisionWindow: false,
          metrics: computeMetricBundle(
            multiSub.map((p) => p.fc),
            multiSub.map((p) => p.act),
            mapeGuardMw
          ),
        });
      }
    }
  }

  const byHourOfDay: HourlyBreakdownRow[] = [];
  for (let hr = 0; hr < 24; hr++) {
    const sub = allPoints.filter((p) => p.hourOfDay === hr);
    if (sub.length > 0) {
      byHourOfDay.push({
        hour: hr,
        hourLabel: `${pad2(hr)}:00`,
        metrics: computeMetricBundle(
          sub.map((p) => p.forecastGenerationMw as number),
          sub.map((p) => p.actualGenerationMw as number),
          mapeGuardMw
        ),
      });
    }
  }

  const binEdges: Array<[string, number, number, number]> = [
    ['<-525', -99999, -525, -600],
    ['-450', -525, -375, -450],
    ['-300', -375, -225, -300],
    ['-150', -225, -75, -150],
    ['0', -75, 75, 0],
    ['+150', 75, 225, 150],
    ['+300', 225, 375, 300],
    ['+450', 375, 525, 450],
    ['>+525', 525, 99999, 600],
  ];
  const errorHistogram: ErrorHistogramBin[] = binEdges.map(([lbl, lo, hi, center]) => {
    const cnt = allPoints.filter((p) => {
      const e = p.errorMw ?? 0;
      return e >= lo && e < hi;
    }).length;
    return { binLabel: lbl, binCenterMw: center, count: cnt };
  });

  return {
    startDate,
    endDate,
    decisionCutoffTimeUk: cutoffTimeUk,
    mapeGuardThresholdMw: mapeGuardMw,
    overall,
    coverageSummaryText,
    procurementGuidanceText,
    byHorizon,
    byHourOfDay,
    byDay,
    errorHistogram,
  };
}
